import assert from "node:assert/strict";
import {readFileSync} from "node:fs";
const read=p=>JSON.parse(readFileSync(new URL("../"+p,import.meta.url),"utf8"));
const base="data/customs/master/";
const sweep=read(base+"customs-weiser-direct-primary-page-sweep-20261029.v1.json");
const earlier=read(base+"customs-a1-12-verified-weiser-facsimile-20261029.v1.json");
const a1=read(base+"customs-a1-150-evidence-and-indulgence-triage-20261029.v1.json");
const byId=new Map(a1.records.map(x=>[x.provisional_group_id,x]));
const prior=new Set(earlier.cases.map(x=>x.provisional_group_id));
const checked=new Set();
assert.equal(sweep.schema,"AO_CUSTOMS_20261029_WEISER_70_DIRECT_SOURCE_SCREEN_V1");
assert.equal(sweep.records.length,72);
assert.equal(prior.size,12);
for (const r of sweep.records) {
 assert.ok(!prior.has(r.group_id),"Previously scanned group duplicated "+r.group_id);
 assert.ok(!checked.has(r.group_id),"New scan duplicated "+r.group_id);
 checked.add(r.group_id);
 const m=byId.get(r.group_id);
 assert.ok(m,"Not in A1 "+r.group_id);
 assert.deepEqual(r.inherited_source_ids,m.source_trace.observation_ids);
 assert.deepEqual(r.source.original_research_printed_page_pointer,m.source_trace.printed_pages);
 assert.ok(m.source_trace.printed_pages.includes(r.source.printed_page_inspected));
 assert.equal(r.source.pdf_page_zero_index,r.source.printed_page_inspected+17);
 assert.equal(r.source.direct_page_visual_review,true);
 assert.match(r.source.url,/^https:\/\/www\.fisheaters\.com\/srpdf\//);
 assert.ok(r.evidence_summary_en.length>=34);
 assert.ok(r.historical_temporal_topic.length>3);
 if (r.source.proposed_corrected_start_page!==null)assert.ok(r.source.proposed_corrected_start_page<r.source.printed_page_inspected);
 assert.equal(r.exact_current_calendar_date_verified,false);
 assert.equal(r.individual_distinct_custom_identity_certified,false);
 assert.equal(r.source_independence_of_secondary_witness_certified,false);
 assert.equal(r.original_whole_page_exhaustively_audited,false);
 assert.equal(r.should_auto_merge_with_canonical,false);
 assert.deepEqual(r.current_indulgence_grant_ids,[]);
 assert.equal(r.indulgence_match_certified,false);
 assert.equal(r.final_english_french_approved,false);
 assert.equal(r.publication_authorized,false);
}
assert.equal(new Set(sweep.records.map(x=>x.source.printed_page_inspected)).size,29);
assert.equal(sweep.counts.checked_source_actions,72);
assert.equal(sweep.counts.primary_page_images_inspected,29);
assert.equal(sweep.counts.cumulative_primary_checked_group_ids,84);
assert.equal(sweep.counts.corrected_or_earlier_start_pointer,15);
assert.equal(sweep.counts.source_title_overclaim_cases,1);
assert.equal(sweep.counts.canonical_identity_approvals,0);
const invalidTitle=sweep.records.filter(x=>!x.source.source_action_confirmed_on_page);
assert.deepEqual(invalidTitle.map(x=>x.group_id),["CAT-WEISER-A-079"]);
assert.ok(invalidTitle[0].evidence_summary_en.includes("does not name a Te Deum"));
assert.equal(new Set([...prior,...checked]).size,84);
assert.equal(a1.records.length-84,66);
console.log("PASS Customs Weiser: 72 new original-page action checks on 29 distinct scanned pages; cumulative A1 84/150; 66 still pending.");
console.log("PASS: specific Te Deum label overclaim held, 15 source-early-start leads, folklore holds, no false calendar, indulgence, canonical or bilingual release.");
